static void
destroy_window_data(SWindowData *window_data) {
  if (window_data == NULL)
    return;

  release_cpp_stub((struct mfb_window *) window_data);

  g_window = NULL;
  vesa_dispose();

  SWindowData_DOS *window_data_specific = (SWindowData_DOS *) window_data->specific;
  if (window_data_specific != NULL) {
