func (f Float3) Sub(other Float3) Float3 {
	return Float3{f.X - other.X, f.Y - other.Y, f.Z - other.Z}
}

func (f Float3) Negate() Float3 {
	return Float3{-f.X, -f.Y, -f.Z}
}

