        name = f"{KEY_NAME_PREFIX}{session_id}-{short_sha}"
        body = {
            "name": name,
            "limit": float(limit_usd),
            "limit_reset": None,
            "include_byok_in_limit": False,
            "expires_at": _utc_iso(expires_at),
        }
