class NetStats:
    def __init__(self):
        self.ping = 0.0
        self.tps = 0.0
        self._ping_sent = None
        self._response_count = 0
        self._tps_start = time.time()

    def sent(self):
        self._ping_sent = time.time()

    def received(self):
        now = time.time()
        if self._ping_sent is not None:
            self.ping = (now - self._ping_sent) * 1000
            self._ping_sent = None
        self._response_count += 1
        elapsed = now - self._tps_start
        if elapsed >= 1.0:
            self.tps = self._response_count / elapsed
            self._response_count = 0
            self._tps_start = now


def connectToServer():
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.connect((SERVER_HOST, SERVER_PORT))
        print(f"Connected to server at {SERVER_HOST}:{SERVER_PORT}")
        return sock
    except Exception as e:
        print(f"Could not connect to server: {e}")
        return None


def receiveThread(sock, recv_queue, local_id, stats):
    buffer = ''
    while True:
        try:
            data = sock.recv(4096)
            if not data:
                break
            buffer += data.decode()
            while '\n' in buffer:
                line, buffer = buffer.split('\n', 1)
                if not line.strip():
                    continue
                msg = json.loads(line)
                stats.received()
                for playerData in msg['players']:
                    if playerData['id'] != local_id:
                        recv_queue.put(playerData)
        except Exception as e:
            print(f"Receive error: {e}")
            break


