#define RING_SIZE 1024

struct ring {
    _Atomic uint32_t head; // producer index
    _Atomic uint32_t tail; // consumer index
    uint8_t data[RING_SIZE];
};

static inline uint32_t load_acquire(_Atomic uint32_t *p) {
    return atomic_load_explicit(p, memory_order_acquire);
}

static inline void store_release(_Atomic uint32_t *p, uint32_t val) {
    atomic_store_explicit(p, val, memory_order_release);
}

// Returns 1 if successful, 0 if full.
int ring_push(struct ring *r, uint8_t byte) {
    uint32_t head = load_acquire(&r->head);
    uint32_t tail = load_acquire(&r->tail);
    if ((head - tail) == RING_SIZE) return 0; // full
    r->data[head & (RING_SIZE - 1)] = byte;
    store_release(&r->head, head + 1);
    return 1;
}

