    uint32_t indirect;
} Inode;

typedef struct {
    uint8_t bitmap[NUM_BLOCKS / 8];
} BlockBitmap;

typedef struct {
    Inode inodes[NUM_BLOCKS * INODES_PER_BLOCK];
} InodeTable;

static BlockBitmap *g_block_bitmap;
static InodeTable *g_inode_table;

static int get_block_bit(int block_num) {
    return (g_block_bitmap->bitmap[block_num / 8] >> (block_num % 8)) & 1;
}

static void set_block_bit(int block_num, int value) {
    if (value)
        g_block_bitmap->bitmap[block_num / 8] |= (1 << (block_num % 8));
    else
        g_block_bitmap->bitmap[block_num / 8] &= ~(1 << (block_num % 8));
}

static int allocate_block(void) {
    for (int i = 0; i < NUM_BLOCKS; i++) {
        if (!get_block_bit(i)) {
            set_block_bit(i, 1);
            return i;
        }
    }
    return -1;
}

static void free_block(int block_num) {
    set_block_bit(block_num, 0);
}

static int find_free_inode(void) {
    for (int i = 0; i < NUM_BLOCKS * INODES_PER_BLOCK; i++) {
        if (g_inode_table->inodes[i].size == 0) {
            return i;
        }
    }
    return -1;
}

static void clear_inode(int inode_num) {
    Inode *inode = &g_inode_table->inodes[inode_num];
    inode->size = 0;
    for (int i = 0; i < 12; i++) {
