typedef struct Node {
    int key;
    int height;
    struct Node *left, *right;
} Node;

int max(int a, int b) { return a > b ? a : b; }

int height(Node *n) { return n ? n->height : 0; }

int get_balance(Node *n) { return n ? height(n->left) - height(n->right) : 0; }

Node *new_node(int key) {
    Node *n = (Node *)malloc(sizeof(Node));
    n->key = key;
    n->height = 1;
    n->left = n->right = NULL;
    return n;
}

Node *right_rotate(Node *y) {
    Node *x = y->left;
    Node *T2 = x->right;
    x->right = y;
    y->left = T2;
    y->height = 1 + max(height(y->left), height(y->right));
    x->height = 1 + max(height(x->left), height(x->right));
    return x;
}

Node *left_rotate(Node *x) {
    Node *y = x->right;
    Node *T2 = y->left;
    y->left = x;
    x->right = T2;
    x->height = 1 + max(height(x->left), height(x->right));
    y->height = 1 + max(height(y->left), height(y->right));
    return y;
}

// Insert a key into the AVL tree, return new root.
Node *insert(Node *node, int key) {
    if (!node) return new_node(key);
    if (key < node->key) node->left = insert(node->left, key);
    else if (key > node->key) node->right = insert(node->right, key);
    else return node;

    node->height = 1 + max(height(node->left), height(node->right));
    int bal = get_balance(node);

    // Left Left Case
    if (bal > 1 && key < node->left->key)
        return right_rotate(node);

    // Right Right Case
    if (bal < -1 && key > node->right->key)
        return left_rotate(node);

    // Left Right Case
    if (bal > 1 && key > node->left->key) {
        node->left = left_rotate(node->left);
        return right_rotate(node);
    }

    // Right Left Case
    if (bal < -1 && key < node->right->key) {
        node->right = right_rotate(node->right);
        return left_rotate(node);
    }

    return node;
}

// Check if the tree is a valid BST and compute its height.
int check_bst(Node *n, int min, int max) {
    if (!n) return 1;
    if (n->key <= min || n->key >= max) return 0;
    return check_bst(n->left, min, n->key) && check_bst(n->right, n->key, max);
}

int compute_height(Node *n) {
    if (!n) return 0;
    int l = compute_height(n->left);
    int r = compute_height(n->right);
    if (l == -1 || r == -1 || abs(l - r) > 1) return -1;
    return 1 + (l > r ? l : r);
}

