class Serializer:
    _TYPE_MARKERS = {int: 1, str: 2, Node: 3}

    @classmethod
    def _serialize_primitive(cls, obj):
        if isinstance(obj, int):
            return struct.pack('>Bi', cls._TYPE_MARKERS[int], obj)
        if isinstance(obj, str):
            data = obj.encode('utf-8')
            return struct.pack('>BI', cls._TYPE_MARKERS[str], len(data)) + data
        raise TypeError(f'Unsupported type: {type(obj)}')

    @classmethod
    def _deserialize_primitive(cls, data, offset):
        marker = data[offset]
        offset += 1
        if marker == cls._TYPE_MARKERS[int]:
            value = struct.unpack_from('>i', data, offset)[0]
            return value, offset + 4
        if marker == cls._TYPE_MARKERS[str]:
            length = struct.unpack_from('>I', data, offset)[0]
            offset += 4
            value = data[offset:offset+length].decode('utf-8')
            return value, offset + length
        raise ValueError(f'Unknown marker: {marker}')

