	for _, v := range []float32{p.maxTrust, p.currentTrustPercentage, p.baseMass, p.fuelMass, p.currentFuelPercentage, p.burnRate, p.burnWithoutAfterburner} {
		_, err = w.Write(float32ToBytes(v))
		if err != nil {
			return err
		}
	}

	return w.Flush()
}

