func (f Float3) Dot(other Float3) float32 {
	return f.X*other.X + f.Y*other.Y + f.Z*other.Z
}

func (f Float3) Cross(other Float3) Float3 {
	return Float3{
		X: f.Y*other.Z - f.Z*other.Y,
		Y: f.Z*other.X - f.X*other.Z,
		Z: f.X*other.Y - f.Y*other.X,
	}
