				obj.ColorMap[y][x] = uint32(r[i]) | uint32(g[i])<<8 | uint32(b[i])<<16 | uint32(a[i])<<24
			}
		}
	}
	if r, g, b, _ := openAndResize(mat.MapBump); r != nil {
		for y := range texSize {
