		}
	}
	if r, _, _, _ := openAndResize(mat.MapRefl); r != nil {
		for y := range texSize {
			for x := range texSize {
				obj.MaterialMap[y][x][1] = r[y*texSize+x]
			}
		}
	}

	return true
}

