	inputFile := os.Args[1]
	outputFile := os.Args[2]

	obj, err := parseObjFile(inputFile)
	if err != nil {
		fmt.Printf("Error parsing OBJ file: %v\n", err)
		os.Exit(1)
	}

	err = writeFile(outputFile, obj, nil)
