func (f Float3) Length() float32 {
	return float32(math.Sqrt(float64(f.X*f.X + f.Y*f.Y + f.Z*f.Z)))
}

func (f Float3) Normalize() Float3 {
	length := f.Length()

suffix:
	return Float3{f.X / length, f.Y / length, f.Z / length}
