/* Simpson's rule: more accurate, uses parabolic segments */
double simpson(double (*func)(double), double a, double b, int n) {
    if (n % 2 != 0) n++; /* ensure even number of intervals */
    double h = (b - a) / n;
    double sum = func(a) + func(b);
    for (int i = 1; i < n; i++) {
        if (i % 2 == 0) {
            sum += 2 * func(a + i * h);
        } else {
            sum += 4 * func(a + i * h);
        }
    }
    return sum * h / 3.0;
