static int count_entries(const char *path, int depth) {
    struct dirent *entry;
    DIR *dp = opendir(path);
    if (!dp) return 0;
    int total = 0;
    while ((entry = readdir(dp)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;
        char full[PATH_MAX];
        snprintf(full, sizeof(full), "%s/%s", path, entry->d_name);
        struct stat st;
        if (stat(full, &st) == 0) {
            total++;
            if (S_ISDIR(st.st_mode) && depth > 0)
                total += count_entries(full, depth - 1);
        }
    }
    closedir(dp);
    return total;
}

static void collect_dirs(const char *base, int depth, char out[][PATH_MAX], int *count) {
    struct dirent *entry;
    DIR *dp = opendir(base);
    if (!dp) return;
    while ((entry = readdir(dp)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;
        char full[PATH_MAX];
        snprintf(full, sizeof(full), "%s/%s", base, entry->d_name);
        struct stat st;
        if (stat(full, &st) == 0 && S_ISDIR(st.st_mode)) {
            if (depth == 0) {
                strncpy(out[(*count)++], full, PATH_MAX - 1);
            } else {
                collect_dirs(full, depth - 1, out, count);
            }
        }
    }
    closedir(dp);
}

