#define MOD 1000000007

typedef struct { long long a[2][2]; } Mat;

Mat mat_mul(Mat x, Mat y) {
    Mat r;
    int i, j, k;
    for (i = 0; i < 2; i++)
        for (j = 0; j < 2; j++) {
            r.a[i][j] = 0;
            for (k = 0; k < 2; k++)
                r.a[i][j] = (r.a[i][j] + x.a[i][k] * y.a[k][j]) % MOD;
        }
    return r;
}

Mat mat_pow(Mat base, int exp) {
    Mat res = {{{1, 0}, {0, 1}}};
    while (exp) {
        if (exp & 1) res = mat_mul(res, base);
        base = mat_mul(base, base);
        exp >>= 1;
    }
    return res;
}

long long fib(int n) {
    if (n < 0) return 0;
    if (n == 0) return 0;
    if (n == 1) return 1;
    Mat base = {{{1, 1}, {1, 0}}};
    Mat p = mat_pow(base, n - 1);
    return p.a[0][0];
}

