type Edge struct {
	u, v, w int
}

func find(parent []int, x int) int {
	if parent[x] != x {
		parent[x] = find(parent, parent[x])
	}
	return parent[x]
}

func union(parent, rank []int, x, y int) {
	xr, yr := find(parent, x), find(parent, y)
	if xr == yr {
		return
	}
	if rank[xr] < rank[yr] {
		parent[xr] = yr
	} else if rank[xr] > rank[yr] {
		parent[yr] = xr
	} else {
		parent[yr] = xr
		rank[xr]++
	}
}

