import "fmt"

// graph is an adjacency list representation of a directed acyclic graph.
// Nodes are ints from 0 to n-1. Edges are given as pairs (from, to).
func buildGraph(n int, edges [][2]int) [][]int {
	g := make([][]int, n)
	for _, e := range edges {
		g[e[0]] = append(g[e[0]], e[1])
	}
	return g
}

// topologicalSort returns a topological ordering of the graph if it is a DAG,
// otherwise returns nil. It uses DFS with a visited state: 0=unvisited, 1=visiting, 2=done.
// The ordering is built in reverse order of finish times.
func topologicalSort(g [][]int) []int {
	n := len(g)
	state := make([]int, n)
	order := make([]int, 0, n)
	var dfs func(int) bool
	dfs = func(v int) bool {
		state[v] = 1
		for _, u := range g[v] {
			if state[u] == 1 {
				return false // cycle detected
			}
			if state[u] == 0 {
				if !dfs(u) {
					return false
				}
			}
		}
		state[v] = 2
		order = append(order, v)
		return true
	}
	for i := 0; i < n; i++ {
		if state[i] == 0 {
			if !dfs(i) {
				return nil
			}
		}
	}
	// Reverse order to get topological order.
	for i, j := 0, len(order)-1; i < j; i, j = i+1, j-1 {
		order[i], order[j] = order[j], order[i]
	}
	return order
}

// maxPathLength computes the length of the longest path in a DAG using dynamic programming.
// It returns the maximum number of edges in any path from any start to any end.
func maxPathLength(g [][]int) int {
	n := len(g)
	// dp[v] = longest path length starting from v (in edges).
	dp := make([]int, n)
	var dfs func(int) int
	dfs = func(v int) int {
		if dp[v] != 0 {
			return dp[v]
		}
		best := 0
		for _, u := range g[v] {
			if cand := 1 + dfs(u); cand > best {
				best = cand
			}
		}
		dp[v] = best
		return best
	}
	maxLen := 0
	for i := 0; i < n; i++ {
		if cand := dfs(i); cand > maxLen {
			maxLen = cand
		}
	}
	return maxLen
}

