func lex(input string) []token {
	var tokens []token
	for i := 0; i < len(input); {
		switch {
		case input[i] == ' ' || input[i] == '\t':
			i++
		case input[i] == '(' || input[i] == ')':
			tokens = append(tokens, token{"paren", string(input[i])})
			i++
		case input[i] == '+' || input[i] == '-' || input[i] == '*':
			tokens = append(tokens, token{"op", string(input[i])})
			i++
		default:
			start := i
			for i < len(input) && input[i] != ' ' && input[i] != '(' && input[i] != ')' {
				i++
			}
			tokens = append(tokens, token{"num", input[start:i]})
		}
	}
	return tokens
}

