// cleanup holds a chain of deferred cleanup functions.
type cleanup struct {
	fns []func() error
}

func (c *cleanup) add(fn func() error) {
	c.fns = append(c.fns, fn)
}

// run executes all cleanup functions in reverse order, collecting errors.
func (c *cleanup) run() error {
	var errs []error
	for i := len(c.fns) - 1; i >= 0; i-- {
		if err := c.fns[i](); err != nil {
			errs = append(errs, err)
		}
	}
	return errors.Join(errs...)
}

// processFile reads a file and returns the number of bytes read.
// It ensures the file is closed and errors are aggregated.
func processFile(ctx context.Context, path string) (n int, err error) {
	f, err := os.Open(path)
	if err != nil {
		return 0, err
	}
	var c cleanup
	c.add(func() error { return f.Close() })
	defer func() {
		if cerr := c.run(); cerr != nil {
			err = errors.Join(err, cerr)
		}
	}()

	buf := make([]byte, 1024)
	for {
		select {
		case <-ctx.Done():
			return n, ctx.Err()
		default:
			read, rerr := f.Read(buf)
			n += read
			if rerr != nil {
				if errors.Is(rerr, os.ErrClosed) {
					return n, rerr
				}
				// on read error, we must still attempt cleanup
				return n, rerr
			}
			if read == 0 {
				return n, nil
			}
		}
	}
}

