const (
	rootDir = "./data"
	manifest = "manifest.txt"
)

// hashFile returns the hex SHA-256 of the given file.
func hashFile(path string) (string, error) {
	f, err := os.Open(path)
	if err != nil {
		return "", err
	}
	defer f.Close()

	h := sha256.New()
	if _, err := io.Copy(h, f); err != nil {
		return "", err
	}
	return hex.EncodeToString(h.Sum(nil)), nil
}

// walkAndHash returns a map from relative path to its hash.
// It skips directories and the manifest itself.
func walkAndHash() (map[string]string, error) {
	result := make(map[string]string)
	err := filepath.Walk(rootDir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if info.IsDir() {
			return nil
		}
		rel, err := filepath.Rel(rootDir, path)
		if err != nil {
			return err
		}
		if rel == manifest {
			return nil
		}
		hash, err := hashFile(path)
		if err != nil {
			return err
		}
		result[rel] = hash
		return nil
	})
	return result, err
}

// verify checks that the current files match the manifest.
// It returns a slice of messages describing any mismatches.
func verify(manifestPath string, expected map[string]string) []string {
	current, err := walkAndHash()
	if err != nil {
		return []string{fmt.Sprintf("error walking: %v", err)}
	}
	var issues []string
	for rel, hash := range expected {
		curHash, ok := current[rel]
		if !ok {
			issues = append(issues, fmt.Sprintf("missing: %s", rel))
			continue
		}
		if curHash != hash {
			issues = append(issues, fmt.Sprintf("modified: %s", rel))
		}
	}
	for rel := range current {
		if _, ok := expected[rel]; !ok {
			issues = append(issues, fmt.Sprintf("extra: %s", rel))
		}
	}
	return issues
}

func main() {
	dataDir := rootDir
	if len(os.Args) > 1 {
		dataDir = os.Args[1]
	}
	manifestPath := filepath.Join(dataDir, manifest)

	// Read and parse the manifest.
	content, err := os.ReadFile(manifestPath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error reading manifest: %v\n", err)
		os.Exit(1)
	}
	expected := make(map[string]string)
	for line := range strings.Lines(string(content)) {
		parts := strings.Fields(line)
		if len(parts) != 2 {
			continue
		}
		expected[parts[0]] = parts[1]
	}

	issues := verify(manifestPath, expected)
	if len(issues) == 0 {
		fmt.Println("all files intact")
	} else {
		for _, msg := range issues {
			fmt.Println(msg)
		}
	}
}

