// parseDigits consumes consecutive digits and returns the integer value.
func parseDigits(s string) (int, int) {
	i := 0
	for i < len(s) && s[i] >= '0' && s[i] <= '9' {
		i++
	}
	if i == 0 {
		return 0, 0
	}
	val := 0
	for j := 0; j < i; j++ {
		val = val*10 + int(s[j]-'0')
	}
	return val, i
}

// parsePair parses a pair of integers separated by a comma, returns the pair and remaining string.
func parsePair(s string) (int, int, string, error) {
	a, n := parseDigits(s)
	if n == 0 {
		return 0, 0, s, fmt.Errorf("expected digit")
	}
	s = s[n:]
	if len(s) == 0 || s[0] != ',' {
		return 0, 0, s, fmt.Errorf("expected comma")
	}
	s = s[1:]
	b, m := parseDigits(s)
	if m == 0 {
		return 0, 0, s, fmt.Errorf("expected digit")
	}
	s = s[m:]
	return a, b, s, nil
}

