// Matrix is a 2D slice of float64 values.
type Matrix [][]float64

// NewMatrix creates an n x n identity matrix.
func NewMatrix(n int) Matrix {
    m := make(Matrix, n)
    for i := range m {
        m[i] = make([]float64, n)
        m[i][i] = 1
    }
    return m
}

// Multiply returns the product of two matrices.
func Multiply(a, b Matrix) Matrix {
    n := len(a)
    c := make(Matrix, n)
    for i := range c {
        c[i] = make([]float64, n)
        for j := range c[i] {
            for k := 0; k < n; k++ {
                c[i][j] += a[i][k] * b[k][j]
            }
        }
    }
    return c
}

// Inverse computes the inverse of a matrix using Gaussian elimination.
// It returns an error if the matrix is singular.
func Inverse(m Matrix) (Matrix, error) {
    n := len(m)
    if n == 0 || len(m[0]) != n {
        return nil, fmt.Errorf("invalid matrix size")
    }
    aug := make(Matrix, n)
    for i := range aug {
        aug[i] = make([]float64, 2*n)
        copy(aug[i], m[i])
        aug[i][n+i] = 1
    }
    for i := 0; i < n; i++ {
        // Find pivot row
        pivot := i
        for j := i + 1; j < n; j++ {
            if abs(aug[j][i]) > abs(aug[pivot][i]) {
                pivot = j
            }
        }
        if abs(aug[pivot][i]) < 1e-12 {
            return nil, fmt.Errorf("singular matrix")
        }
        if pivot != i {
            aug[i], aug[pivot] = aug[pivot], aug[i]
        }
        // Normalize pivot row
        div := aug[i][i]
        for j := 0; j < 2*n; j++ {
            aug[i][j] /= div
        }
        // Eliminate other rows
        for j := 0; j < n; j++ {
            if j != i {
                factor := aug[j][i]
                if factor != 0 {
                    for k := 0; k < 2*n; k++ {
                        aug[j][k] -= factor * aug[i][k]
                    }
                }
            }
        }
    }
    // Extract the right half
    inv := make(Matrix, n)
    for i := range inv {
        inv[i] = make([]float64, n)
        copy(inv[i], aug[i][n:])
    }
    return inv, nil
}

func abs(x float64) float64 {
    if x < 0 {
        return -x
    }
    return x
}

