// Determinant computes the determinant of a square matrix using expansion by minors.
// It uses the first row for expansion, which is efficient for small matrices.
func Determinant(m Matrix) (float64, error) {
    n := len(m)
    if n == 0 || len(m[0]) != n {
        return 0, fmt.Errorf("invalid matrix size")
    }
    if n == 1 {
        return m[0][0], nil
    }
    if n == 2 {
        return m[0][0]*m[1][1] - m[0][1]*m[1][0], nil
    }
    det := 0.0
    for j := 0; j < n; j++ {
        // Build submatrix removing row 0 and column j
        sub := make(Matrix, n-1)
        for i := 1; i < n; i++ {
            sub[i-1] = make([]float64, n-1)
            k := 0
            for col := 0; col < n; col++ {
                if col == j {
                    continue
                }
                sub[i-1][k] = m[i][col]
                k++
            }
        }
        subDet, err := Determinant(sub)
        if err != nil {
            return 0, err
        }
        sign := 1.0
        if j%2 == 1 {
            sign = -1.0
        }
        det += sign * m[0][j] * subDet
    }
    return det, nil
}

