	return tokenPattern.FindAllString(s, -1)
}

func parse(s string) []string {
	tokens := tokenize(s)
	if len(tokens) == 0 || len(tokens) > maxTokens {
		return nil
	}
	var out []string
	for i := 0; i < len(tokens); i++ {
		tok := tokens[i]
		if tok == "..." {
			out = append(out, "VARARGS")
			continue
		}
		if tok == "." {
			if i+1 < len(tokens) && tokens[i+1] == "." && i+2 < len(tokens) && tokens[i+2] == "." {
				out = append(out, "ELLIPSIS")
				i += 2
				continue
			}
			out = append(out, "DOT")
			continue
		}
		if tok[0] >= '0' && tok[0] <= '9' {
			out = append(out, "NUM:"+tok)
			continue
		}
		out = append(out, "ID:"+tok)
	}
	return out
}

func classify(tokens []string) string {
	if len(tokens) == 0 {
		return "EMPTY"
	}
	first := tokens[0]
	if strings.HasPrefix(first, "NUM:") {
		return "NUMERIC"
	}
	if strings.HasPrefix(first, "ID:") {
		return "IDENTIFIER"
	}
	switch first {
	case "VARARGS", "ELLIPSIS":
		return "SPECIAL"
	default:
		return "SYMBOL"
	}
}

