class Header:
    __slots__ = ('magic', 'version', 'flags')
    MAGIC = 0x5A5A
    VERSION = 1

    def __init__(self, magic: int, version: int, flags: int):
        self.magic = magic
        self.version = version
        self.flags = flags

    def pack(self) -> bytes:
        return struct.pack('<HHI', self.magic, self.version, self.flags)

    @classmethod
    def unpack(cls, buffer: bytes) -> 'Header':
        magic, version, flags = struct.unpack('<HHI', buffer)
        return cls(magic, version, flags)

class Payload:
    __slots__ = ('kind', 'data')

    def __init__(self, kind: int, data: bytes):
        self.kind = kind
        self.data = data

    def pack(self) -> bytes:
        return struct.pack('<BI', self.kind, len(self.data)) + self.data

    @classmethod
    def unpack(cls, buffer: bytes) -> 'Payload':
        kind, length = struct.unpack('<BI', buffer[:5])
        data = buffer[5:5+length]
        return cls(kind, data)

def serialize(header: Header, payloads: Tuple[Payload, ...]) -> bytes:
    header_b = header.pack()
    count = len(payloads)
    # The wire format: header (8 bytes), then a 4-byte count, then each payload.
    # Each payload is packed with its own header (kind and length) followed by raw data.
    body = b''.join(p.pack() for p in payloads)
    return header_b + struct.pack('<I', count) + body

def deserialize(data: bytes) -> Tuple[Header, Tuple[Payload, ...]]:
    header = Header.unpack(data[:8])
    count = struct.unpack('<I', data[8:12])[0]
    offset = 12
    payloads = []
    for _ in range(count):
        p = Payload.unpack(data[offset:])
        payloads.append(p)
        offset += 5 + len(p.data)
    return header, tuple(payloads)

