async function retryFetch(url, retries = MAX_RETRIES) {
  let attempt = 0;
  while (attempt < retries) {
    try {
      return await fetchWithTimeout(url, TIMEOUT_MS);
    } catch (err) {
      attempt++;
      if (attempt >= retries) throw new Error(`Failed after ${attempt} attempts: ${err.message}`);
      const backoff = BASE_DELAY * Math.pow(2, attempt - 1);
      await delay(backoff);
    }
  }
}

