function getProjectStructure(rootDir) {
  const result = { directories: [], files: [] };

  function walk(dir, depth) {
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    for (const entry of entries) {
      if (isIgnored(entry.name, entry.isDirectory())) continue;
      const fullPath = path.join(dir, entry.name);
      const relativePath = path.relative(rootDir, fullPath);
      if (entry.isDirectory()) {
        result.directories.push({ path: relativePath, depth });
        walk(fullPath, depth + 1);
      } else {
        result.files.push({ path: relativePath, depth });
      }
    }
  }

  walk(rootDir, 0);
  return result;
}

