// Runs a task in a worker thread, returning a promise.
function runInWorker(taskFn, arg) {
  return new Promise((resolve, reject) => {
    const worker = new Worker(`
      const { parentPort } = require('worker_threads');
      parentPort.on('message', (data) => {
        const result = ${taskFn.toString()}(data);
        parentPort.postMessage(result);
      });
    `, { eval: true });
    worker.once('message', resolve);
    worker.once('error', reject);
    worker.postMessage(arg);
  });
}

// Distribute tasks across the available CPU cores, but with a twist:
// we need to stagger the start times to avoid all workers finishing at once.
async function parallelWithStagger(tasks, staggerMs) {
  const numWorkers = os.cpus().length;
  const results = new Array(tasks.length);
  let nextIndex = 0;
  async function workerLoop() {
    while (true) {
      const index = nextIndex++;
      if (index >= tasks.length) break;
      // Wait for the stagger delay before starting this task.
      await new Promise(r => setTimeout(r, staggerMs * index));
      results[index] = await runInWorker(heavyTask, tasks[index]);
    }
  }
  const workers = Array.from({ length: numWorkers }, workerLoop);
  await Promise.all(workers);
  return results;
}

