    enum token_type type;
    char lexeme[MAX_TOKEN_LEN];
};

/* Helper: check if character can start an identifier */
static int is_ident_start(char c) {
    return isalpha((unsigned char)c) || c == '_';
}

/* Helper: check if character can continue an identifier */
static int is_ident_part(char c) {
    return isalnum((unsigned char)c) || c == '_';
}

/* Helper: check if character is a digit */
static int is_digit(char c) {
    return c >= '0' && c <= '9';
}

/* Helper: check if character is a symbol (non-alphanumeric, non-space) */
static int is_symbol(char c) {
    return !isspace((unsigned char)c) && !isalnum((unsigned char)c) && c != '\0';
}

/* Core tokenizer: extracts the next token from input starting at pos.
 * Returns 1 if token extracted, 0 if end of string, -1 on error (token too long).
 * Updates pos to point after the token. */
static int next_token(const char *input, int *pos, struct token *tok) {
    int start = *pos;
    int len = 0;
    char c;

    /* Skip leading whitespace */
    while (input[*pos] != '\0' && isspace((unsigned char)input[*pos])) {
        (*pos)++;
    }
    start = *pos;
    c = input[*pos];

    if (c == '\0') {
        tok->type = TOK_END;
        tok->lexeme[0] = '\0';
        return 0;
    }

    if (is_ident_start(c)) {
        /* Identifier */
        while (input[*pos] != '\0' && is_ident_part(input[*pos])) {
            if (len < MAX_TOKEN_LEN - 1) {
                tok->lexeme[len++] = input[*pos];
            } else {
                return -1;
            }
            (*pos)++;
        }
        tok->lexeme[len] = '\0';
        tok->type = TOK_IDENT;
        return 1;
    }

    if (is_digit(c)) {
        /* Number: simple integer or float */
        while (input[*pos] != '\0' && (is_digit(input[*pos]) || input[*pos] == '.')) {
            if (len < MAX_TOKEN_LEN - 1) {
                tok->lexeme[len++] = input[*pos];
            } else {
                return -1;
            }
            (*pos)++;
        }
        tok->lexeme[len] = '\0';
        tok->type = TOK_NUMBER;
        return 1;
    }

    if (is_symbol(c)) {
        /* Single-character symbol */
        tok->lexeme[0] = c;
        tok->lexeme[1] = '\0';
        tok->type = TOK_SYMBOL;
        (*pos)++;
        return 1;
    }

    /* Unreachable */
    return -1;
}

