import "fmt"

// findOrder returns a topological ordering of courses given prerequisite pairs.
// Each pair [a, b] means course b must be taken before course a.
// If no valid ordering exists, returns nil.
func findOrder(numCourses int, prerequisites [][]int) []int {
    graph := make([][]int, numCourses)
    for _, p := range prerequisites {
        graph[p[0]] = append(graph[p[0]], p[1])
    }
    state := make([]int, numCourses) // 0=unvisited, 1=visiting, 2=visited
    order := make([]int, 0, numCourses)
    var dfs func(int) bool
    dfs = func(course int) bool {
        if state[course] == 1 {
            return false
        }
        if state[course] == 2 {
            return true
        }
        state[course] = 1
        for _, prereq := range graph[course] {
            if !dfs(prereq) {
                return false
            }
        }
        state[course] = 2
        order = append(order, course)
        return true
    }
    for c := 0; c < numCourses; c++ {
        if state[c] == 0 {
            if !dfs(c) {
                return nil
            }
        }
    }
    return order
}

