// serialize converts a header to its wire representation.
func serialize(h header) []byte {
	buf := make([]byte, 16)
	binary.LittleEndian.PutUint16(buf[0:2], h.Magic)
	buf[2] = h.Version
	buf[3] = h.Flags
	binary.LittleEndian.PutUint32(buf[4:8], h.Size)
	copy(buf[8:16], h.Data[:])
	return buf
}

// deserialize converts wire bytes back to a header.
func deserialize(b []byte) header {
	var h header
	h.Magic = binary.LittleEndian.Uint16(b[0:2])
	h.Version = b[2]
	h.Flags = b[3]
	h.Size = binary.LittleEndian.Uint32(b[4:8])
	copy(h.Data[:], b[8:16])
	return h
}

