// marshallCompact packs the header into a tightly packed byte slice using unsafe,
// ensuring the struct is laid out without padding.
func marshallCompact(h header) []byte {
	size := unsafe.Sizeof(h)
	aligned := alignTo(size, 8)
	buf := make([]byte, aligned)
	ptr := (*header)(unsafe.Pointer(&buf[0]))
	*ptr = h
	return buf[:size]
