// modular exponentiation: compute (base^exp) mod mod
func modPow(base, exp, mod int64) int64 {
    result := int64(1)
    base = base % mod
    for exp > 0 {
        if exp%2 == 1 {
            result = (result * base) % mod
        }
        exp = exp >> 1
        base = (base * base) % mod
    }
    return result
}

// Chinese Remainder Theorem: given pairwise coprime moduli m1, m2, m3,
// and remainders r1, r2, r3, find x such that x ≡ ri (mod mi).
func crt3(r1, r2, r3, m1, m2, m3 int64) int64 {
    M := m1 * m2 * m3
    // compute M_i = M / m_i and its modular inverse mod m_i
    M1 := M / m1
    M2 := M / m2
    M3 := M / m3
    inv1 := modPow(M1%m1, m1-2, m1)
    inv2 := modPow(M2%m2, m2-2, m2)
    inv3 := modPow(M3%m3, m3-2, m3)
    // combine using formula x = sum(r_i * M_i * inv_i) mod M
    x := (r1*M1%M)*inv1%M + (r2*M2%M)*inv2%M + (r3*M3%M)*inv3%M
    return x % M
}

