// transformWord applies the vowel-reversal rule to a single word.
// It converts each vowel rune to its uppercase form if the word starts
// with a consonant, otherwise to its lowercase form. Non-vowel runes
// are left unchanged.
func transformWord(word string) string {
	if word == "" {
		return word
	}
	first := rune(word[0])
	if isVowel(first) {
		return strings.Map(func(r rune) rune {
			if isVowel(r) {
				return unicode.ToLower(r)
			}
			return r
		}, word)
	}
	return strings.Map(func(r rune) rune {
		if isVowel(r) {
			return unicode.ToUpper(r)
		}
		return r
	}, word)
}

// processText normalizes spaces, splits into words, applies transformWord
// to each word, and rejoins them with single spaces.
func processText(s string) string {
	normalized := normalizeSpaces(s)
	words := strings.Fields(normalized)
	for i, w := range words {
		words[i] = transformWord(w)
	}
	return strings.Join(words, " ")
}

