)

type token struct {
	kind string
	val  string
}

type parser struct {
	tokens []token
	pos    int
}

func (p *parser) peek() token {
	if p.pos >= len(p.tokens) {
		return token{kind: "EOF"}
	}
	return p.tokens[p.pos]
}

func (p *parser) next() token {
	t := p.peek()
	p.pos++
	return t
}

func tokenize(s string) []token {
	var toks []token
	for _, r := range s {
		if r == ' ' {
			continue
		}
		switch r {
		case '+', '-', '*', '/', '(', ')':
			toks = append(toks, token{kind: "op", val: string(r)})
		default:
			toks = append(toks, token{kind: "num", val: string(r)})
		}
	}
	return toks
}

func (p *parser) parseExpr() int {
	left := p.parseTerm()
	for p.peek().kind == "op" && (p.peek().val == "+" || p.peek().val == "-") {
		op := p.next().val
		right := p.parseTerm()
		if op == "+" {
			left += right
		} else {
			left -= right
		}
	}
	return left
}

func (p *parser) parseTerm() int {
	factor := p.parseFactor()
	for p.peek().kind == "op" && (p.peek().val == "*" || p.peek().val == "/") {
		op := p.next().val
		right := p.parseFactor()
		if op == "*" {
			factor *= right
		} else {
			factor /= right
		}
	}
	return factor
}

