import (
	"bytes"
	"encoding/binary"
	"errors"
	"fmt"
	"io"
)

const magic uint32 = 0x0DEFACED

// Version 1 of the serialization format.
// Each entry is: length (uint32), data (length bytes), checksum (uint32).
// Checksum is CRC32 of data using IEEE polynomial.

type Entry struct {
	Data []byte
	Checksum uint32
}

// encodeEntry writes one entry to w.
func encodeEntry(w io.Writer, e Entry) error {
	if len(e.Data) == 0 {
		return errors.New("empty data")
	}
	if err := binary.Write(w, binary.LittleEndian, uint32(len(e.Data))); err != nil {
		return err
	}
	if _, err := w.Write(e.Data); err != nil {
		return err
	}
	return binary.Write(w, binary.LittleEndian, e.Checksum)
}

// decodeEntry reads one entry from r.
func decodeEntry(r io.Reader) (Entry, error) {
	var length uint32
	if err := binary.Read(r, binary.LittleEndian, &length); err != nil {
		return Entry{}, err
	}
	if length > 1<<20 {
		return Entry{}, errors.New("entry too large")
	}
	data := make([]byte, length)
	if _, err := io.ReadFull(r, data); err != nil {
		return Entry{}, err
	}
	var checksum uint32
	if err := binary.Read(r, binary.LittleEndian, &checksum); err != nil {
		return Entry{}, err
	}
	return Entry{Data: data, Checksum: checksum}, nil
}

// writeCollection serializes a header (magic + count) followed by all entries.
func writeCollection(w io.Writer, entries []Entry) error {
	hdr := struct {
		Magic uint32
		Count uint32
	}{magic, uint32(len(entries))}
	if err := binary.Write(w, binary.LittleEndian, hdr); err != nil {
		return err
	}
	for _, e := range entries {
		if err := encodeEntry(w, e); err != nil {
			return err
		}
	}
	return nil
}

// validate checksum using CRC32 (IEEE).
func validateChecksum(e Entry) bool {
	return crc32.ChecksumIEEE(e.Data) == e.Checksum
}

