import struct

class Packet:
    def __init__(self, seq, data):
        self.seq = seq
        self.data = data

def compute_crc(data):
    crc = 0xFFFF
    for byte in data:
        crc ^= byte
        for _ in range(8):
            if crc & 1:
                crc = (crc >> 1) ^ 0xA001
            else:
                crc >>= 1
    return crc

def pack_packet(pkt):
    body = struct.pack('>I', pkt.seq) + pkt.data
    header = struct.pack('>I', len(body))
    return header + body

def unpack_packet(stream):
    if len(stream) < 4:
        return None, 0
    size = struct.unpack('>I', stream[:4])[0]
    if len(stream) < 4 + size:
        return None, 0
    body = stream[4:4+size]
    seq = struct.unpack('>I', body[:4])[0]
    data = body[4:]
    return Packet(seq, data), 4 + size

