    crc = compute_crc(body)
    return pack_packet(pkt) + struct.pack('>H', crc)

def deserialize_packet(stream):
    pkt, consumed = unpack_packet(stream)
    if pkt is None:
        return None, 0
    if len(stream) < consumed + 2:
        return None, 0
    crc = struct.unpack('>H', stream[consumed:consumed+2])[0]
    body = stream[4:consumed]
    if crc != compute_crc(body):
        raise ValueError('CRC mismatch')
    return pkt, consumed + 2

