        return -1;
    }
    *result = a + b;
    return 0;
}

static int safe_mul(int a, int b, int *result) {
    if (a == 0 || b == 0) {
        *result = 0;
        return 0;
    }
    if (a > 0) {
        if (b > 0) {
            if (a > INT_MAX / b) return -1;
        } else {
            if (b < INT_MIN / a) return -1;
        }
    } else {
        if (b > 0) {
            if (a < INT_MIN / b) return -1;
        } else {
            if (a != 0 && b < INT_MAX / a) return -1;
        }
    }
    *result = a * b;
    return 0;
}

static int find_gcd(int a, int b) {
    while (b != 0) {
        int t = b;
        b = a % b;
        a = t;
    }
    return a < 0 ? -a : a;
}

static int find_lcm(int a, int b, int *result) {
    if (a == 0 || b == 0) {
        *result = 0;
        return 0;
    }
    int g = find_gcd(a, b);
    int q = a / g;  // a is divisible by g
    return safe_mul(q, b, result);
}

