// wordFreq returns a map of word to frequency, ignoring case and punctuation.
func wordFreq(s string) map[string]int {
	f := strings.FieldsFunc(s, func(r rune) bool {
		return !unicode.IsLetter(r) && !unicode.IsNumber(r)
	})
	m := make(map[string]int)
	for _, w := range f {
		m[strings.ToLower(w)]++
	}
	return m
}

// maxFreq returns the maximum frequency value in the map.
func maxFreq(m map[string]int) int {
	max := 0
	for _, v := range m {
		if v > max {
			max = v
		}
	}
	return max
}

// topWords returns the top n words by frequency, then alphabetically.
// It uses a custom sort to break ties.
func topWords(m map[string]int, n int) []string {
	type kv struct {
		word string
		freq int
	}
	items := make([]kv, 0, len(m))
	for w, f := range m {
		items = append(items, kv{w, f})
	}
	sort.Slice(items, func(i, j int) bool {
		if items[i].freq != items[j].freq {
			return items[i].freq > items[j].freq
		}
		return items[i].word < items[j].word
	})
	if n > len(items) {
		n = len(items)
	}
	res := make([]string, n)
	for i := 0; i < n; i++ {
		res[i] = items[i].word
	}
	return res
}

// summarize takes a text and returns a summary string.
// It lists the top 5 words by frequency, and also the total number of unique words.
func summarize(text string) string {
	freq := wordFreq(text)
	top := topWords(freq, 5)
	total := len(freq)
	max := maxFreq(freq)

	// Build the summary using a strings.Builder to avoid repeated concatenation.
	var b strings.Builder
	b.WriteString("Top words: ")
	for i, w := range top {
		if i > 0 {
			b.WriteString(", ")
		}
		b.WriteString(w)
	}
	b.WriteString(fmt.Sprintf(" (total unique: %d, max frequency: %d)", total, max))
	return b.String()
}

