#include <stdint.h>
#include <stddef.h>

#define MAX_ITEMS 16
#define HEADER_SIZE 4

struct Record {
    uint8_t id;
    uint16_t value;
};

// Serialize a record into a 3-byte little-endian buffer
void serialize_record(const struct Record *r, uint8_t *buf) {
    buf[0] = r->id;
    buf[1] = (uint8_t)(r->value & 0xFF);
    buf[2] = (uint8_t)((r->value >> 8) & 0xFF);
}

// Pack an array of records into a byte stream with a header
// header: first byte = count, next 3 bytes = reserved (zero-filled)
// each record takes 3 bytes
size_t pack_records(const struct Record *records, size_t count,
                    uint8_t *out, size_t out_cap) {
    if (count > MAX_ITEMS || out_cap < HEADER_SIZE + count * 3) {
        return 0;
    }
    out[0] = (uint8_t)count;
    out[1] = 0;
    out[2] = 0;
    out[3] = 0;
    for (size_t i = 0; i < count; i++) {
        serialize_record(&records[i], out + HEADER_SIZE + i * 3);
    }
    return HEADER_SIZE + count * 3;
}

// Unpack a byte stream back into records, validating the header
int unpack_records(const uint8_t *in, size_t in_len,
                   struct Record *records, size_t max_records) {
    if (in_len < HEADER_SIZE) return -1;
    size_t count = in[0];
    if (count > MAX_ITEMS || count > max_records) return -1;
    if (in_len != HEADER_SIZE + count * 3) return -1;
    for (size_t i = 0; i < count; i++) {
        const uint8_t *p = in + HEADER_SIZE + i * 3;
        records[i].id = p[0];
        records[i].value = (uint16_t)(p[1] | (p[2] << 8));
    }
    return (int)count;
}

