func (p *Pool) Get(ctx context.Context) (net.Conn, error) {
	p.mu.Lock()
	defer p.mu.Unlock()

	for len(p.conns) > 0 {
		c := p.conns[len(p.conns)-1]
		p.conns = p.conns[:len(p.conns)-1]
		if c != nil {
			return c, nil
		}
	}

	if len(p.conns) >= p.max {
		return nil, errors.New("pool exhausted")
	}

	select {
	case <-ctx.Done():
		return nil, ctx.Err()
	default:
	}

	conn, err := net.DialTimeout("tcp", "localhost:8080", p.timeout)
	if err != nil {
		return nil, err
	}
	return conn, nil
}

