import "fmt"

// isPrime reports whether n is prime.
func isPrime(n int) bool {
    if n < 2 {
        return false
    }
    for i := 2; i*i <= n; i++ {
        if n%i == 0 {
            return false
        }
    }
    return true
}

// phi computes Euler's totient function for n.
func phi(n int) int {
    result := n
    for p := 2; p*p <= n; p++ {
        if n%p == 0 {
            for n%p == 0 {
                n /= p
            }
            result -= result / p
        }
    }
    if n > 1 {
        result -= result / n
    }
    return result
}

// modPow computes (base^exp) mod mod using fast exponentiation.
func modPow(base, exp, mod int) int {
    if mod == 1 {
        return 0
    }
    result := 1
    base %= mod
    for exp > 0 {
        if exp&1 == 1 {
            result = (result * base) % mod
        }
        base = (base * base) % mod
        exp >>= 1
    }
    return result
}

