const maxFiles = 3

// openSequentially opens files in order, returning the first error encountered.
// If any open fails, it returns an error that includes which file failed.
func openSequentially(paths []string) error {
	var firstErr error
	for i, p := range paths {
		if i >= maxFiles {
			break
		}
		f, err := os.Open(p)
		if err != nil {
			firstErr = fmt.Errorf("file %d: %w", i, err)
			break
		}
		f.Close()
	}
	return firstErr
}

// closeAll attempts to close every closer, aggregating errors.
func closeAll(closers ...interface{ Close() error }) error {
	var errs []error
	for _, c := range closers {
		if err := c.Close(); err != nil {
			errs = append(errs, err)
		}
	}
	return errors.Join(errs...)
}

