func parseConfig(r *bufio.Reader) (config, error) {
	var c config
	c.port = defaultPort
	lineNum := 0
	for {
		line, err := r.ReadString('\n')
		if err != nil && line == "" {
			break
		}
		lineNum++
		if lineNum > maxLines {
			return c, fmt.Errorf("too many lines")
		}
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		parts := strings.SplitN(line, "=", 2)
		if len(parts) != 2 {
			return c, fmt.Errorf("invalid line %d", lineNum)
		}
		key := strings.TrimSpace(parts[0])
		val := strings.TrimSpace(parts[1])
		switch key {
		case "port":
			var p int
			if _, err := fmt.Sscanf(val, "%d", &p); err != nil {
				return c, fmt.Errorf("bad port")
			}
			c.port = p
		case "host":
			c.host = val
		}
	}
	return c, nil
}

