// nodeCount is the number of nodes in the graph.
const nodeCount = 6

// edges defines directed edges from node i to node j (0-indexed).
// The graph is a DAG: 0->1, 0->2, 1->3, 2->3, 3->4, 4->5.
var edges = [][2]int{
	{0, 1},
	{0, 2},
	{1, 3},
	{2, 3},
	{3, 4},
	{4, 5},
}

// buildAdjMatrix returns a nodeCount x nodeCount adjacency matrix.
func buildAdjMatrix() [][]bool {
	adj := make([][]bool, nodeCount)
	for i := range adj {
		adj[i] = make([]bool, nodeCount)
	}
	for _, e := range edges {
		adj[e[0]][e[1]] = true
	}
	return adj
}

// hasIncoming returns true if any edge points to node v.
func hasIncoming(adj [][]bool, v int) bool {
	for i := 0; i < nodeCount; i++ {
		if adj[i][v] {
			return true
		}
	}
	return false
}

// KahnTopo performs a topological sort using Kahn's algorithm.
// It returns the order as a slice of node indices.
func KahnTopo(adj [][]bool) []int {
	inDegree := make([]int, nodeCount)
	for i := 0; i < nodeCount; i++ {
		for j := 0; j < nodeCount; j++ {
			if adj[i][j] {
				inDegree[j]++
			}
		}
	}
	queue := []int{}
	for i := 0; i < nodeCount; i++ {
		if inDegree[i] == 0 {
			queue = append(queue, i)
		}
	}
	order := []int{}
	for len(queue) > 0 {
		u := queue[0]
		queue = queue[1:]
		order = append(order, u)
		for v := 0; v < nodeCount; v++ {
			if adj[u][v] {
				inDegree[v]--
				if inDegree[v] == 0 {
					queue = append(queue, v)
				}
			}
		}
	}
	return order
}

