// DFS performs a depth-first traversal starting from node start,
// visiting all reachable nodes and recording the order of visitation.
func DFS(adj [][]bool, start int) []int {
	visited := make([]bool, nodeCount)
	order := []int{}
	var dfs func(v int)
	dfs = func(v int) {
		visited[v] = true
		order = append(order, v)
		for w := 0; w < nodeCount; w++ {
			if adj[v][w] && !visited[w] {
				dfs(w)
			}
		}
	}
	dfs(start)
	return order
}

// isDAG checks if the graph is a DAG by verifying that Kahn's algorithm
// returns a full ordering of all nodes.
func isDAG(adj [][]bool) bool {
	order := KahnTopo(adj)
	return len(order) == nodeCount
}

