#define IRQ_MAX 32
#define TIMER_IRQ 3
#define UART_IRQ 5

static volatile uint32_t irq_pending;
static volatile uint32_t irq_enabled;
static void (*irq_handlers[IRQ_MAX])(void);

static void enable_irq(uint32_t irq) {
    irq_enabled |= (1u << irq);
    __asm volatile("cpsie i");
}

static void disable_irq(uint32_t irq) {
    irq_enabled &= ~(1u << irq);
    __asm volatile("cpsid i");
}

void irq_register(uint32_t irq, void (*handler)(void)) {
    if (irq < IRQ_MAX) {
        disable_irq(irq);
        irq_handlers[irq] = handler;
        enable_irq(irq);
    }
}

static void dispatch_irqs(void) {
    uint32_t pending = irq_pending & irq_enabled;
    while (pending) {
        uint32_t bit = pending & -pending;
        uint32_t irq = __builtin_ctz(bit);
        irq_pending &= ~bit;
        if (irq_handlers[irq]) {
            irq_handlers[irq]();
        }
        pending = irq_pending & irq_enabled;
    }
}

void irq_trigger(uint32_t irq) {
    __asm volatile("cpsid i");
    irq_pending |= (1u << irq);
    __asm volatile("cpsie i");
}

