  traverse(dir, (file) => {
    const stat = fs.statSync(file);
    snapshot[file] = { size: stat.size, mtimeMs: stat.mtimeMs };
  });
  return snapshot;
}

function diffSnapshots(before, after) {
  const changes = [];
  const allKeys = new Set([...Object.keys(before), ...Object.keys(after)]);
  for (const key of allKeys) {
    if (!before[key] || !after[key] || before[key].size !== after[key].size || before[key].mtimeMs !== after[key].mtimeMs) {
      changes.push(key);
    }
  }
  return changes;
}

function applySync(changes, sourceDir, backupDir) {
  for (const file of changes) {
    const rel = path.relative(sourceDir, file);
    const dest = path.join(backupDir, rel);
    fs.mkdirSync(path.dirname(dest), { recursive: true });
    fs.copyFileSync(file, dest);
  }
}

function watchAndSync(sourceDir, backupDir, intervalMs = 5000) {
  let lastSnapshot = collectSnapshot(sourceDir);
  let pendingChanges = new Set();
  let timer = null;

  const processPending = () => {
    if (pendingChanges.size === 0) return;
    const changes = Array.from(pendingChanges);
    pendingChanges.clear();
    applySync(changes, sourceDir, backupDir);
    lastSnapshot = collectSnapshot(sourceDir);
    timer = null;
  };

  const scheduleProcess = () => {
    if (timer) return;
    timer = setTimeout(processPending, intervalMs);
  };

  fs.watch(sourceDir, { recursive: true }, (eventType, filename) => {
    if (!filename) return;
    const full = path.join(sourceDir, filename);
    const rel = path.relative(sourceDir, full);
    if (IGNORED.has(rel.split(path.sep)[0])) return;
    const stat = fs.existsSync(full) ? fs.statSync(full) : null;
    if (stat && stat.isDirectory()) return;
    const current = stat ? { size: stat.size, mtimeMs: stat.mtimeMs } : null;
    const prev = lastSnapshot[full];
    if (!current || !prev || current.size !== prev.size || current.mtimeMs !== prev.mtimeMs) {
      pendingChanges.add(full);
      scheduleProcess();
    }
  });

  return () => {
    if (timer) clearTimeout(timer);
    if (fs.watch) fs.unwatchFile(sourceDir);
  };
}

