package main

import "fmt"

// Node is a binary tree node.
type Node struct {
	Val   int
	Left  *Node
	Right *Node
}

// buildTree constructs a balanced BST from a sorted slice.
func buildTree(nums []int, lo, hi int) *Node {
	if lo > hi {
		return nil
	}
	mid := (lo + hi) / 2
	n := &Node{Val: nums[mid]}
	n.Left = buildTree(nums, lo, mid-1)
	n.Right = buildTree(nums, mid+1, hi)
	return n
}

// serializeNode writes the node value and then recursively serializes children.
func serializeNode(n *Node, out *[]int) {
	if n == nil {
		return
	}
	*out = append(*out, n.Val)
	serializeNode(n.Left, out)
	serializeNode(n.Right, out)
}

func main() {
	nums := []int{1, 2, 3, 4, 5, 6, 7}
	root := buildTree(nums, 0, len(nums)-1)
	var order []int
	serializeNode(root, &order)
	fmt.Println(order)
}

