// Preorder traversal is implemented in serializeNode above.
// But that function uses a pointer to a slice. Here we demonstrate
// an alternative: return the slice directly. This is the same
// traversal but with a different signature.
func preorder(n *Node) []int {
	if n == nil {
		return nil
	}
	result := []int{n.Val}
	result = append(result, preorder(n.Left)...)
	result = append(result, preorder(n.Right)...)
	return result
}

