// shortestPath returns the minimum cost to go from start to end in a grid
// where 0 is open and 1 is blocked. Moves are only up/down/left/right.
func shortestPath(grid [][]int, start, end [2]int) int {
	rows := len(grid)
	if rows == 0 {
		return -1
	}
	cols := len(grid[0])
	if grid[start[0]][start[1]] == 1 || grid[end[0]][end[1]] == 1 {
		return -1
	}
	dist := make([][]int, rows)
	for i := range dist {
		dist[i] = make([]int, cols)
		for j := range dist[i] {
			dist[i][j] = 1e9
		}
	}
	dist[start[0]][start[1]] = 0
	pq := &PriorityQueue{}
	heap.Init(pq)
	heap.Push(pq, &Item{value: start, priority: 0})
	dirs := [][2]int{{0, 1}, {1, 0}, {0, -1}, {-1, 0}}
	for pq.Len() > 0 {
		item := heap.Pop(pq).(*Item)
		pos := item.value.([2]int)
		if pos == end {
			return item.priority
		}
		for _, d := range dirs {
			nr, nc := pos[0]+d[0], pos[1]+d[1]
			if nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == 0 {
				newDist := item.priority + 1
				if newDist < dist[nr][nc] {
					dist[nr][nc] = newDist
					heap.Push(pq, &Item{value: [2]int{nr, nc}, priority: newDist})
				}
			}
		}
	}
	return -1
}

