#include <stdlib.h>

typedef struct Node {
    int key;
    int height;
    struct Node *left, *right;
} Node;

static int max(int a, int b) { return a > b ? a : b; }

static int height(Node *n) { return n ? n->height : 0; }

static Node *new_node(int key) {
    Node *n = malloc(sizeof(Node));
    n->key = key;
    n->height = 1;
    n->left = n->right = NULL;
    return n;
}

static Node *rotate_right(Node *y) {
    Node *x = y->left;
    Node *T2 = x->right;
    x->right = y;
    y->left = T2;
    y->height = 1 + max(height(y->left), height(y->right));
    x->height = 1 + max(height(x->left), height(x->right));
    return x;
}

static Node *rotate_left(Node *x) {
    Node *y = x->right;
    Node *T2 = y->left;
    y->left = x;
    x->right = T2;
    x->height = 1 + max(height(x->left), height(x->right));
    y->height = 1 + max(height(y->left), height(y->right));
    return y;
}

static int get_balance(Node *n) { return n ? height(n->left) - height(n->right) : 0; }

Node *insert(Node *node, int key) {
    if (!node) return new_node(key);
    if (key < node->key) node->left = insert(node->left, key);
    else if (key > node->key) node->right = insert(node->right, key);
    else return node;
    node->height = 1 + max(height(node->left), height(node->right));
    int bal = get_balance(node);
    // Left Left Case
    if (bal > 1 && key < node->left->key) return rotate_right(node);
    // Left Right Case
    if (bal > 1 && key > node->left->key) {
        node->left = rotate_left(node->left);
        return rotate_right(node);
    }
    // Right Right Case
    if (bal < -1 && key > node->right->key) return rotate_left(node);
    // Right Left Case
    if (bal < -1 && key < node->right->key) {
        node->right = rotate_right(node->right);
        return rotate_left(node);
    }
    return node;
}

void free_tree(Node *node) {
    if (node) {
        free_tree(node->left);
        free_tree(node->right);
        free(node);
    }
}

